import time
from selenium.webdriver.remote.webelement import WebElement
from selenium.webdriver.support.wait import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.by import By
from typing import Optional as opt
from selenium.common.exceptions import TimeoutException

def _wait(wait: int) -> None:
    # Breaking this out into its own fucntion for now as I feel like we may want to expand this with logging/output in the future.
    if wait == 0:
        time.sleep(0.5)
        return
    time.sleep(wait)


class ElementFunctions:

    @staticmethod
    def element_is_enabled(driver, web_element: WebElement, wait_timeout: int = 5,
                           scroll_element_to_view: bool=False) -> bool:
        try:
            if scroll_element_to_view:
                _ = web_element.location_once_scrolled_into_view
            if WebDriverWait(driver, timeout=wait_timeout).until(EC.element_to_be_clickable((web_element))):
                return True
            return False
        except Exception as e:
            print("Element not found, click not performed. Exception caught: " + str(e))
            return False

    @staticmethod
    def element_click(driver, web_element: WebElement, wait_timeout: int = 10,
                      wait_after_click: int = 0, scroll_element_to_view: bool=False) -> None:
        try:
            if scroll_element_to_view:
                _ = web_element.location_once_scrolled_into_view
            WebDriverWait(driver, timeout=wait_timeout).until(EC.element_to_be_clickable((web_element)))
            web_element.click()
            _wait(wait_after_click)
        except Exception as e:
            print("Element not found, click not performed. Exception caught: " + str(e))
            return None

    @staticmethod
    def element_get_text_content(driver, web_element: WebElement) -> opt[str]:
        try:
            WebDriverWait(driver, timeout=10).until(EC.element_to_be_clickable((web_element)))
            return web_element.get_attribute("textContent")
        except Exception as e:
            print("Element not found, unable to return text content. Exception caught: " + str(e))
            return None

    @staticmethod
    def element_text_to_be_present(driver, css_selector: str,
                                   text_in_element: str, wait_timeout: int = 10) -> bool:
        try:
            WebDriverWait(driver, timeout=wait_timeout).until(
                EC.text_to_be_present_in_element((By.CSS_SELECTOR, css_selector), text_in_element))
            return True
        except Exception as e:
            print("Element text not found. Exception caught: " + str(e))
            return False

    @staticmethod
    def element_get_childElementCount(driver, web_element: WebElement) -> opt[str]:
        try:
            WebDriverWait(driver, timeout=10).until(EC.element_to_be_clickable((web_element)))
            return web_element.get_attribute("childElementCount")
        except Exception as e:
            print("Element not found, unable to return child element count. Exception caught: " + str(e))
            return None

    @staticmethod
    def element_is_visible(driver, web_element: WebElement) -> bool:
        try:
            WebDriverWait(driver, timeout=10).until(EC.visibility_of(web_element))
            return True
        except Exception as e:
            print("Element is not visible. Exception caught: " + str(e))
            return False

    @staticmethod
    def element_input(driver, web_element: WebElement, input: str) -> None:
        try:
            ElementFunctions.element_click(driver, web_element)
            web_element.send_keys(input)
        except Exception as e:
            print("Error inputting text in element. Exception caught: " + str(e))
            return None

    @staticmethod
    def element_is_enabled_from_class_attribute(driver, web_element: WebElement, element_selector: str,
                                                wait_timeout:int = 3, scroll_element_to_view: bool=False) -> bool:
        try:
            if scroll_element_to_view:
                _ = web_element.location_once_scrolled_into_view
            WebDriverWait(driver, timeout=wait_timeout).until_not(
                EC.text_to_be_present_in_element_attribute((By.CSS_SELECTOR, element_selector), "class", "disabled"))
            return True

        except TimeoutException as e:
            # Expected when the wait condition is not satisifed within the timeout
            print("Element class attribute value condtion not found: " + str(e))
            return False
        except Exception as e:
            # Raise exception for all other errors
            raise Exception("Error getting class attribute value from element. Exception caught: " + str(e))
